using System.ComponentModel;
using Microsoft.Extensions.AI;

// --- Tool Definitions ---

/// <summary>Tools for web searching and note-taking used by the research agent.</summary>
public static class ResearchTools
{
    private static readonly List<string> _notes = [];
    private static readonly HttpClient _http = new();

    [Description("Search the web for information on a given query. Returns a list of result snippets.")]
    public static async Task<string> SearchWeb(string query)
    {
        Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");

        // Use a public search API (DuckDuckGo Instant Answer API) for demonstration
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

        try
        {
            var json = await _http.GetStringAsync(url);
            // Extract the Abstract and RelatedTopics text as search results
            var doc = System.Text.Json.JsonDocument.Parse(json);
            var results = new List<string>();

            var abstractText = doc.RootElement.GetProperty("Abstract").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
                results.Add($"Summary: {abstractText}");

            if (doc.RootElement.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text) && !string.IsNullOrWhiteSpace(text.GetString()))
                        results.Add(text.GetString()!);
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : "No results found. Try a different search query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Save a research note. Use this to record key findings during research.")]
    public static string SaveNote(string note)
    {
        Console.WriteLine($"  [Tool] Saving note: \"{note[..Math.Min(note.Length, 80)]}...\"");
        _notes.Add(note);
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes.")]
    public static string GetNotes()
    {
        Console.WriteLine("  [Tool] Retrieving all notes");
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n---\n", _notes.Select((n, i) => $"[Note {i + 1}]: {n}"));
    }
}

// --- Main Program ---

Console.WriteLine("=== Research Agent ===\n");

var topic = args.Length > 0
    ? string.Join(" ", args)
    : "the latest advances in quantum computing in 2026";

Console.WriteLine($"Research topic: {topic}\n");

// Configure the AI client (uses OPENAI_API_KEY and optionally OPENAI_MODEL env vars)
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "no-key";
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var endpoint = Environment.GetEnvironmentVariable("OPENAI_BASE_URL");

OpenAI.OpenAIClient openAiClient = endpoint is not null
    ? new(new System.ClientModel.ApiKeyCredential(apiKey), new OpenAI.OpenAIClientOptions { Endpoint = new Uri(endpoint) })
    : new(new System.ClientModel.ApiKeyCredential(apiKey));

IChatClient innerClient = openAiClient.GetChatClient(model).AsIChatClient();

// Wrap with tool-calling support
IChatClient agent = new ChatClientBuilder(innerClient)
    .UseFunctionInvocation()
    .Build();

// Define available tools
var tools = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(ResearchTools.SearchWeb),
        AIFunctionFactory.Create(ResearchTools.SaveNote),
        AIFunctionFactory.Create(ResearchTools.GetNotes),
    ]
};

var systemPrompt = $"""
    You are a research agent. Your task is to research the following topic thoroughly:
    "{topic}"

    Follow this process:
    1. Search the web for information about the topic using multiple queries
    2. Save important findings as notes using the SaveNote tool
    3. After gathering enough information, retrieve your notes and provide a comprehensive summary

    Be thorough but concise. Make at least 2-3 different searches to get varied perspectives.
    End with a clear, well-structured summary of your findings.
    """;

var messages = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Please research this topic: {topic}")
};

Console.WriteLine("Agent is researching...\n");

var response = await agent.GetResponseAsync(messages, tools);

Console.WriteLine("\n=== Research Complete ===\n");
Console.WriteLine(response.Text);

