Console.WriteLine("\n=== Research Complete ===\n");
Console.WriteLine(response.Text);

// --- Tool Definitions ---

/// <summary>Tools for web searching and note-taking used by the research agent.</summary>
public static class ResearchTools
{
    private static readonly List<string> _notes = [];
    private static readonly HttpClient _http = new();

    [Description("Search the web for information on a given query. Returns a list of result snippets.")]
    public static async Task<string> SearchWeb(string query)
    {
        Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");

        var encoded = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

        try
        {
            var json = await _http.GetStringAsync(url);
            var doc = System.Text.Json.JsonDocument.Parse(json);
            var results = new List<string>();

            var abstractText = doc.RootElement.GetProperty("Abstract").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
                results.Add($"Summary: {abstractText}");

            if (doc.RootElement.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text) && !string.IsNullOrWhiteSpace(text.GetString()))
                        results.Add(text.GetString()!);
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : "No results found. Try a different search query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Save a research note. Use this to record key findings during research.")]
    public static string SaveNote(string note)
    {
        Console.WriteLine($"  [Tool] Saving note: \"{note[..Math.Min(note.Length, 80)]}...\"");
        _notes.Add(note);
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes.")]
    public static string GetNotes()
    {
        Console.WriteLine("  [Tool] Retrieving all notes");
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n---\n", _notes.Select((n, i) => $"[Note {i + 1}]: {n}"));
    }
}

